def find_orfs(s, minaa=150):
    res=[]
    L=len(s)
    for frame in range(3):
        prot=translate(s[frame:])
        # positions of stops
        stops=[i for i,aa in enumerate(prot) if aa=='*']
        segs=[]
        prev=-1
        for st in stops:
            segs.append((prev+1, st))
            prev=st
        segs.append((prev+1, len(prot)))
        for a,b in segs:
            if b-a>=minaa:
                res.append((frame, a, b, prot[a:b]))
    return res

